  },
  titleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  logo: {
    width: 40,
    height: 40,
    borderRadius: 8,
  },
  titleText: {
    color: THEME.text.primary,
    fontSize: 24,
    fontWeight: 'bold',
    fontFamily: Platform.select({ web: 'Cinzel, serif', default: 'System' }),
  },
  controls: {
    flexDirection: 'row',
    gap: 12,
    flexWrap: 'wrap',
  },
  button: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: THEME.primary.accent,
    paddingHorizontal: 16,
    paddingVertical: 10,
    borderRadius: 8,
    gap: 8,
    borderWidth: 1,
    borderColor: THEME.border.light,
  },
  buttonActive: {
    backgroundColor: THEME.secondary.main,
    borderColor: THEME.secondary.light,
  },
  buttonText: {
    color: THEME.text.primary,
    fontSize: 14,
    fontWeight: '600',
  },
  buttonIcon: {
    fontSize: 16,
    color: THEME.text.primary,
  },
  roomInfo: {
    backgroundColor: THEME.primary.light,
    padding: 8,
    borderRadius: 6,
    borderWidth: 1,
    borderColor: THEME.border.light,
  },
  roomText: {
    color: THEME.text.secondary,
    fontSize: 12,
  },
  dmBadge: {
    backgroundColor: THEME.secondary.main,
    paddingHorizontal: 8,
    paddingVertical: 4,
    borderRadius: 6,
    marginLeft: 12,
  },
  dmBadgeText: {
    color: THEME.text.primary,
    fontSize: 12,
    fontWeight: 'bold',
  },
});

// Add main content styles after headerStyles
const mainStyles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: THEME.primary.main,
  },
  content: {
    flex: 1,
  },
  contentWrapper: {
    flexDirection: initialIsSmallScreen ? 'column' : 'row',
    maxWidth: 1600, // Increased to give more room
    marginHorizontal: 'auto',
    width: '100%',
    padding: 20,
    gap: 20,
  },
  toolsSection: {
    width: initialIsSmallScreen ? '100%' : 250, // Fixed width instead of flex
    minWidth: 250,
  },
  gridSection: {
    flex: 2, // Grid takes up more space
    backgroundColor: THEME.primary.light,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: THEME.border.medium,
    overflow: 'hidden',
  },
  gridHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 16,
    borderBottomWidth: 1,
    borderBottomColor: THEME.border.medium,
    backgroundColor: THEME.primary.accent,
  },
  sectionTitle: {
    color: THEME.text.primary,
    fontSize: 18,
    fontWeight: '600',
  },
  gridControls: {
    flexDirection: 'row',
    gap: 8,
